    SELECT p.id, 7, 24, NULL,
        NULL, NULL, NULL,
        NULL, NULL, '{"targetTags": ["예비부모/난임", "임산부", "출산/입양", "농업인", "어업인", "축산업인", "임업인", "근로자/직장인", "구직자/실업자", "장애인", "국가보훈대상자", "질병/질환자", "다문화가족", "북한이탈주민", "한부모가정/조손가정", "1인가구", "다자녀가구", "무주택세대", "신규전입", "확대가족"]}'::jsonb FROM p
