-- SD0000012704 중소기업자간 경쟁제품 및 공사용자재 직접구매
WITH p AS (
    INSERT INTO policies (organization_id, title, summary, description, target_description,
        benefit_description, application_method, application_type, application_start_date,
        application_end_date, region_scope, status, source_url, source_updated_at, last_verified_at)
    VALUES ((SELECT id FROM organizations WHERE name = '중소벤처기업부' ORDER BY id LIMIT 1),
        '중소기업자간 경쟁제품 및 공사용자재 직접구매', '중소기업자간 경쟁제품'' 등에 지정된 품목은 공공기관에서 제한 또는 지명경쟁으로 조달', '중소기업 제품의 구매 촉진 및 판로 지원',
        '○ 중소기업 기본법 제2조에 따른 중소기업자', '○ 중 기간 경쟁제품, 공사용 자재 직접구매
 - 지원대상 : 공공기관 연간 구매액이 10억원 이상의 기본요건을 충족하는 품목, 직접구매(분리발주) 대상 공사의 범위
 - 직접구매(분리발주) 대상 공사의 범위 : 건설산업기본법상의 종합공사는 40억원 이상인 공사, 전문건설공사 및 전기/통신공사/소방시설공사 등 전문공사는 3억원 이상인 공사로 직접구매 대상품목의 추정가격이 4천만원 이상인 공사
 - 지원내용 : 공공기관 입찰시 중소기업자 간 경쟁제품 대상품목은 직접생산확인을 받은 중소기업 간에 제한경쟁 또는 지명경쟁하며, 입찰방식은 계약이행능력심사를 통해 낙찰 가격을 보장, 공사용 자재 중 직접구매 대상으로 분리된 품목은 공공기관이 중소기업으로부터 분리 발주하여 직접구매', '중소기업자 간 경쟁제품 및 공사용 자재 직접구매 품목 지정 신청은 관련 조합, 한국벤처기업협회, 중소기업기술혁신협회가 신청하거나 해당 제품을 직접 생산, 제공하는 10개 이상의 중소기업이 연명하여 신청(신청양식은 공공구매종합정보망의 공지사항에서 "중소기업자 간 경쟁제품 지정"으로 검색하여 서식다운)',
        'UNKNOWN', NULL, NULL,
        'NATIONAL', 'OPEN', 'https://www.gov.kr/portal/rcvfvrSvc/dtlEx/SD0000012704',
        TIMESTAMP '2026-08-12 14:20:02', TIMESTAMP '2026-09-23 01:14:36')
    RETURNING id
), c AS (
    INSERT INTO policy_categories (policy_id, category_id)
    SELECT p.id, c.id FROM p, categories c WHERE c.code IN ('EMPLOYMENT')
), e AS (
    INSERT INTO policy_eligibility (policy_id, minimum_age, maximum_age, gender_condition, income_type,
        minimum_income_value, maximum_income_value, allowed_employment_statuses,
        allowed_household_types, additional_conditions)
    SELECT p.id, NULL, NULL, NULL,
        NULL, NULL, NULL,
        NULL, NULL, '{"selectionCriteria": "○ 중소기업자", "targetTags": ["예비창업자", "영업중", "생계곤란/폐업예정자"]}'::jsonb FROM p
), a AS (
    INSERT INTO policy_application_info (policy_id, application_procedure, required_documents_text,
        application_url, contact_info, application_notes, source_url, verified_at)
    SELECT p.id, '중소기업자 간 경쟁제품 및 공사용 자재 직접구매 품목 지정 신청은 관련 조합, 한국벤처기업협회, 중소기업기술혁신협회가 신청하거나 해당 제품을 직접 생산, 제공하는 10개 이상의 중소기업이 연명하여 신청(신청양식은 공공구매종합정보망의 공지사항에서 "중소기업자 간 경쟁제품 지정"으로 검색하여 서식다운)', '신청서, 사업자등록증', 'http://www.smpp.go.kr',
        '중소기업중앙회/02-2124-3241', '신청기한: 공공구매종합정보망 공지사항 참조
접수기관: 중소기업중앙회', 'https://www.gov.kr/portal/rcvfvrSvc/dtlEx/SD0000012704', TIMESTAMP '2026-09-23 01:14:36' FROM p
)
